//! release.yml is generated by dist, plus one hand edit: the job that
//! publishes (`host`) also waits for the checks. dist's own condition accepts
//! skipped builds, and failing checks skip them, so without the edit a tag on
//! a broken commit would publish a release with no binaries. Regenerating
//! the file drops the edit; this test notices.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::path::Path;

#[test]
fn the_release_is_only_published_once_the_checks_pass() {
    let workflow = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join(".github/workflows/release.yml"),
    )
    .unwrap();
    let host = workflow
        .split("\n  host:\n")
        .nth(1)
        .expect("release.yml has a `host` job");
    let host = host.split("\n    steps:").next().unwrap();
    assert!(
        host.contains("      - custom-checks\n")
            && host.contains("needs.custom-checks.result == 'success'"),
        "the `host` job in release.yml must need `custom-checks` and require it to succeed; \
         re-apply the hand edit described there after `dist generate`:\n{host}"
    );
}
